use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-endpoints175";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let r=Path::new(R);assert!(!r.join("remaining-native-plan.json").exists());for n in["control-core","control-prover","libraries-control","freeze-control"]{assert_eq!(read(r.join(format!("native/{n}/exit.json")))["success"],true);}assert_eq!(read(r.join("native/replay-control/exit.json"))["success"],false);let old=read(r.join("build-plan.json"));let mut steps=old["steps"].as_array().unwrap()[4..].to_vec();assert_eq!(steps.len(),8);for s in &mut steps{if s["name"]=="replay-control"||s["name"]=="replay-candidate"{let control=s["name"]=="replay-control";let name=if control{"replay-control-fixed"}else{"replay-candidate"};*s=json!({"kind":"command","name":name,"argv":[r.join("link-replay"),if control{"control"}else{"candidate"},r.join("native-remaining").join(name)],"timeout_seconds":600});}else if s["name"]=="freeze-candidate"{s["argv"][0]=json!(r.join("native-fixed"));}}
let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("build-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}for p in["native-fixed.rs","native-fixed","link-replay.rs","link-replay","remaining-native.rs","native/replay-control/stderr.log","native/replay-control/command.json","native/replay-control/exit.json"]{let file=r.join(p);pins.insert(file.display().to_string(),hash(file));}fs::write(r.join("remaining-native-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r.join("remaining-native-plan.json"),serde_json::to_vec_pretty(&json!({"version":1,"source_pins":r.join("remaining-native-pins.json"),"steps":steps})).unwrap()).unwrap();println!("Reuse4completed native steps;8remaining steps; explicit SHA2 replay link; no source/test repeats");}
